; ppi.asm -- appendix C: the PPI's ports, and the slots
; generated by genC.py
        INCLUDE "msx.inc"
        OUTPUT "ppi.rom"
        ORG $4000
        CART_HEADER init

; The PPI, case by case: measC.py reads the PPI and the bytes the program
; kept, from $C000, at each label i<case>.
slots   EQU $C07F       ; port A as the BIOS left it

init:   di
        ld sp,$F370
; slots
        ld hl,slotrt
        ld de,$E100
        ld bc,slotrt_end-slotrt
        ldir                    ; the routine for pages 0 to 2, into the RAM
        ld hl,$4D52
        ld ($E000),hl
        in a,(PPI_A)
        ld (slots),a
        ld a,(slots)
        and $FC
        or $00
        ld b,a                  ; page 0 in slot 0
        ld de,$0000
        call $E100
        ld ($C000),hl
        ld a,(slots)
        and $FC
        or $01
        ld b,a                  ; page 0 in slot 1
        ld de,$0000
        call $E100
        ld ($C002),hl
        ld a,(slots)
        and $FC
        or $02
        ld b,a                  ; page 0 in slot 2
        ld de,$0000
        call $E100
        ld ($C004),hl
        ld a,(slots)
        and $FC
        or $03
        ld b,a                  ; page 0 in slot 3
        ld de,$0000
        call $E100
        ld ($C006),hl
        ld a,(slots)
        and $F3
        or $00
        ld b,a                  ; page 1 in slot 0
        ld de,$4000
        call $E100
        ld ($C008),hl
        ld a,(slots)
        and $F3
        or $04
        ld b,a                  ; page 1 in slot 1
        ld de,$4000
        call $E100
        ld ($C00A),hl
        ld a,(slots)
        and $F3
        or $08
        ld b,a                  ; page 1 in slot 2
        ld de,$4000
        call $E100
        ld ($C00C),hl
        ld a,(slots)
        and $F3
        or $0C
        ld b,a                  ; page 1 in slot 3
        ld de,$4000
        call $E100
        ld ($C00E),hl
        ld a,(slots)
        and $CF
        or $00
        ld b,a                  ; page 2 in slot 0
        ld de,$8000
        call $E100
        ld ($C010),hl
        ld a,(slots)
        and $CF
        or $10
        ld b,a                  ; page 2 in slot 1
        ld de,$8000
        call $E100
        ld ($C012),hl
        ld a,(slots)
        and $CF
        or $20
        ld b,a                  ; page 2 in slot 2
        ld de,$8000
        call $E100
        ld ($C014),hl
        ld a,(slots)
        and $CF
        or $30
        ld b,a                  ; page 2 in slot 3
        ld de,$8000
        call $E100
        ld ($C016),hl
        ld a,(slots)
        and $3F
        or $00
        ld b,a                  ; page 3 in slot 0
        ld a,(slots)
        ld c,a
        ld a,b
        out (PPI_A),a
        ld hl,($E000)
        ld a,c
        out (PPI_A),a           ; back
        ld ($C018),hl
        ld a,(slots)
        and $3F
        or $40
        ld b,a                  ; page 3 in slot 1
        ld a,(slots)
        ld c,a
        ld a,b
        out (PPI_A),a
        ld hl,($E000)
        ld a,c
        out (PPI_A),a           ; back
        ld ($C01A),hl
        ld a,(slots)
        and $3F
        or $80
        ld b,a                  ; page 3 in slot 2
        ld a,(slots)
        ld c,a
        ld a,b
        out (PPI_A),a
        ld hl,($E000)
        ld a,c
        out (PPI_A),a           ; back
        ld ($C01C),hl
        ld a,(slots)
        and $3F
        or $C0
        ld b,a                  ; page 3 in slot 3
        ld a,(slots)
        ld c,a
        ld a,b
        out (PPI_A),a
        ld hl,($E000)
        ld a,c
        out (PPI_A),a           ; back
        ld ($C01E),hl
islots: nop                     ; measC.py reads the PPI
; cback
        ld hl,$C100
        ld b,0
        ld c,0
cb:     ld a,c
        out (PPI_C),a
        in a,(PPI_C)
        ld (hl),a
        inc hl
        inc c
        djnz cb
        ld a,$50
        out (PPI_C),a
icback: nop                     ; measC.py reads the PPI
; rowwait
        in a,(VDP_CTRL)
        ld e,3
rwrowwait_1: in a,(VDP_CTRL)
        rlca
        jr nc,rwrowwait_1
        dec e
        jr nz,rwrowwait_1       ; to the frame the keys are held
        ld e,6
irowwait: nop                   ; measC.py reads the PPI
; rows
rf:     in a,(VDP_CTRL)
        rlca
        jr nc,rf
        ld hl,$C200
        ld c,0
rr:     ld a,c
        or $50
        out (PPI_C),a
        in a,(PPI_B)
        ld (hl),a
        inc hl
        inc c
        ld a,c
        cp 16
        jr nz,rr                ; rows 0 to 15
irows:  nop                     ; measC.py reads the PPI
; rowsend
        dec e
        jr nz,rf
        ld a,$50
        out (PPI_C),a
irowsend: nop                   ; measC.py reads the PPI
; ctrl
        ld a,$00
        out (PPI_C),a           ; port C = $00
        ld a,$00
        out (PPI_MODE),a        ; bit 0 of C to 0
        in a,(PPI_C)
        ld ($C020),a
        ld a,$00
        out (PPI_C),a           ; port C = $00
        ld a,$01
        out (PPI_MODE),a        ; bit 0 of C to 1
        in a,(PPI_C)
        ld ($C021),a
        ld a,$00
        out (PPI_C),a           ; port C = $00
        ld a,$02
        out (PPI_MODE),a        ; bit 1 of C to 0
        in a,(PPI_C)
        ld ($C022),a
        ld a,$00
        out (PPI_C),a           ; port C = $00
        ld a,$03
        out (PPI_MODE),a        ; bit 1 of C to 1
        in a,(PPI_C)
        ld ($C023),a
        ld a,$00
        out (PPI_C),a           ; port C = $00
        ld a,$04
        out (PPI_MODE),a        ; bit 2 of C to 0
        in a,(PPI_C)
        ld ($C024),a
        ld a,$00
        out (PPI_C),a           ; port C = $00
        ld a,$05
        out (PPI_MODE),a        ; bit 2 of C to 1
        in a,(PPI_C)
        ld ($C025),a
        ld a,$00
        out (PPI_C),a           ; port C = $00
        ld a,$06
        out (PPI_MODE),a        ; bit 3 of C to 0
        in a,(PPI_C)
        ld ($C026),a
        ld a,$00
        out (PPI_C),a           ; port C = $00
        ld a,$07
        out (PPI_MODE),a        ; bit 3 of C to 1
        in a,(PPI_C)
        ld ($C027),a
        ld a,$00
        out (PPI_C),a           ; port C = $00
        ld a,$08
        out (PPI_MODE),a        ; bit 4 of C to 0
        in a,(PPI_C)
        ld ($C028),a
        ld a,$00
        out (PPI_C),a           ; port C = $00
        ld a,$09
        out (PPI_MODE),a        ; bit 4 of C to 1
        in a,(PPI_C)
        ld ($C029),a
        ld a,$00
        out (PPI_C),a           ; port C = $00
        ld a,$0A
        out (PPI_MODE),a        ; bit 5 of C to 0
        in a,(PPI_C)
        ld ($C02A),a
        ld a,$00
        out (PPI_C),a           ; port C = $00
        ld a,$0B
        out (PPI_MODE),a        ; bit 5 of C to 1
        in a,(PPI_C)
        ld ($C02B),a
        ld a,$00
        out (PPI_C),a           ; port C = $00
        ld a,$0C
        out (PPI_MODE),a        ; bit 6 of C to 0
        in a,(PPI_C)
        ld ($C02C),a
        ld a,$00
        out (PPI_C),a           ; port C = $00
        ld a,$0D
        out (PPI_MODE),a        ; bit 6 of C to 1
        in a,(PPI_C)
        ld ($C02D),a
        ld a,$00
        out (PPI_C),a           ; port C = $00
        ld a,$0E
        out (PPI_MODE),a        ; bit 7 of C to 0
        in a,(PPI_C)
        ld ($C02E),a
        ld a,$00
        out (PPI_C),a           ; port C = $00
        ld a,$0F
        out (PPI_MODE),a        ; bit 7 of C to 1
        in a,(PPI_C)
        ld ($C02F),a
        ld a,$FF
        out (PPI_C),a           ; port C = $FF
        ld a,$00
        out (PPI_MODE),a        ; bit 0 of C to 0
        in a,(PPI_C)
        ld ($C030),a
        ld a,$FF
        out (PPI_C),a           ; port C = $FF
        ld a,$01
        out (PPI_MODE),a        ; bit 0 of C to 1
        in a,(PPI_C)
        ld ($C031),a
        ld a,$FF
        out (PPI_C),a           ; port C = $FF
        ld a,$02
        out (PPI_MODE),a        ; bit 1 of C to 0
        in a,(PPI_C)
        ld ($C032),a
        ld a,$FF
        out (PPI_C),a           ; port C = $FF
        ld a,$03
        out (PPI_MODE),a        ; bit 1 of C to 1
        in a,(PPI_C)
        ld ($C033),a
        ld a,$FF
        out (PPI_C),a           ; port C = $FF
        ld a,$04
        out (PPI_MODE),a        ; bit 2 of C to 0
        in a,(PPI_C)
        ld ($C034),a
        ld a,$FF
        out (PPI_C),a           ; port C = $FF
        ld a,$05
        out (PPI_MODE),a        ; bit 2 of C to 1
        in a,(PPI_C)
        ld ($C035),a
        ld a,$FF
        out (PPI_C),a           ; port C = $FF
        ld a,$06
        out (PPI_MODE),a        ; bit 3 of C to 0
        in a,(PPI_C)
        ld ($C036),a
        ld a,$FF
        out (PPI_C),a           ; port C = $FF
        ld a,$07
        out (PPI_MODE),a        ; bit 3 of C to 1
        in a,(PPI_C)
        ld ($C037),a
        ld a,$FF
        out (PPI_C),a           ; port C = $FF
        ld a,$08
        out (PPI_MODE),a        ; bit 4 of C to 0
        in a,(PPI_C)
        ld ($C038),a
        ld a,$FF
        out (PPI_C),a           ; port C = $FF
        ld a,$09
        out (PPI_MODE),a        ; bit 4 of C to 1
        in a,(PPI_C)
        ld ($C039),a
        ld a,$FF
        out (PPI_C),a           ; port C = $FF
        ld a,$0A
        out (PPI_MODE),a        ; bit 5 of C to 0
        in a,(PPI_C)
        ld ($C03A),a
        ld a,$FF
        out (PPI_C),a           ; port C = $FF
        ld a,$0B
        out (PPI_MODE),a        ; bit 5 of C to 1
        in a,(PPI_C)
        ld ($C03B),a
        ld a,$FF
        out (PPI_C),a           ; port C = $FF
        ld a,$0C
        out (PPI_MODE),a        ; bit 6 of C to 0
        in a,(PPI_C)
        ld ($C03C),a
        ld a,$FF
        out (PPI_C),a           ; port C = $FF
        ld a,$0D
        out (PPI_MODE),a        ; bit 6 of C to 1
        in a,(PPI_C)
        ld ($C03D),a
        ld a,$FF
        out (PPI_C),a           ; port C = $FF
        ld a,$0E
        out (PPI_MODE),a        ; bit 7 of C to 0
        in a,(PPI_C)
        ld ($C03E),a
        ld a,$FF
        out (PPI_C),a           ; port C = $FF
        ld a,$0F
        out (PPI_MODE),a        ; bit 7 of C to 1
        in a,(PPI_C)
        ld ($C03F),a
        in a,(PPI_MODE)
        ld ($C040),a            ; the control port read
        ld a,$50
        out (PPI_C),a
ictrl:  nop                     ; measC.py reads the PPI
; phase0
        ld c,$00
        ld a,$00
        out (PPI_C),a           ; lamp, motor on; 5, 7 turn
        ld d,10
        in a,(VDP_CTRL)
phphase0_1: nop
        ld e,40
tgphase0_1: dec e
        jr nz,tgphase0_1
        ld a,c
        xor $A0
        ld c,a
        out (PPI_C),a           ; bits 5 and 7 turned over
        in a,(VDP_CTRL)
        rlca
        jr nc,phphase0_1
        dec d
        jr nz,phphase0_1
iphase0: nop                    ; measC.py reads the PPI
; phase1
        ld a,$D0
        out (PPI_C),a           ; lamp, motor off; click 1
        ld d,10
        in a,(VDP_CTRL)
phphase1_1: nop
        in a,(VDP_CTRL)
        rlca
        jr nc,phphase1_1
        dec d
        jr nz,phphase1_1
iphase1: nop                    ; measC.py reads the PPI
; cend
        ld a,$50
        out (PPI_C),a
icend:  nop                     ; measC.py reads the PPI
done:   jr done

; slotrt: B into port A, the word at DE into HL, port A back; copied to
; $E100, in the RAM, which the slots it sets do not move
slotrt: ld a,(slots)
        ld c,a
        ld a,b
        out (PPI_A),a
        ex de,hl
        ld e,(hl)
        inc hl
        ld d,(hl)
        ld a,c
        out (PPI_A),a           ; back
        ex de,hl
        ret
slotrt_end:

        ASSERT $ <= $8000, the program is longer than the cartridge
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
